SELECT "first_name", "last_name",  ("salary"/"H") AS "dollars per hit" FROM "performances" JOIN "salaries" ON "salaries"."player_id" = "performances"."player_id" AND "salaries"."year" = "performances"."year" JOIN "players" ON "players"."id" = "performances"."player_id" WHERE "H" IS NOT 0 AND "salaries"."year" = 2001 ORDER BY "salary"/"H" ASC, "first_name", "last_name" LIMIT 10; 
